args.sparql:
SELECT ?film (MIN(?death) AS ?minDeath) ?filmLabel WHERE {
  VALUES ?film { dbr:Vice_Raid dbr:The_Courier_of_Lyon }
  ?film dbo:director ?director .
  ?director dbo:deathDate ?death .
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en') }
}
GROUP BY ?film ?filmLabel
ORDER BY ?minDeath
LIMIT 1

